parameters.message:
={{ (() => {
  let s = String($json.output ?? '');
  s = s.replace(/\\n/g, '\n');
  s = s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  s = s.replace(/\*\*?(Datos informados|Referencia encontrada|Datos faltantes|Siguiente paso):\*\*?/gi,
    '<br><br><strong>$1:</strong><br>');
  s = s.replace(/\n/g, '<br>');
  return '<p>Resultado de la ejecución:</p>' + s.replace(/^(<br>)+/, '');
})() }}
